import React, { useState } from "react";
import "../styles/styles.css";
import { gatherPokemonData } from "../scripts/dataHandler.js";
import Hero from "./Hero.jsx";
import FilterMenu from "./FilterMenu.jsx";
import Card from "./Card.jsx";
import Modal from "./Modal.jsx";

const allPokemon = await gatherPokemonData();

export default function App() {
  const [shownPokemon, setShownPokemon] = useState([]);
  const [modalData, setModalData] = useState({});

  return (
    <div>
      <Hero />
      <FilterMenu data={allPokemon} setShown={setShownPokemon} />
      <div className="cards">
        {shownPokemon.map((pokemon) => (
          <Card key={pokemon.num} data={pokemon} setModalData={setModalData} />
        ))}
      </div>
      <Modal data={modalData} />
    </div>
  );
}
