import React from "react";
import closer from "../assets/images/close.svg";
import types from "../data/types.js";

export default function Modal(props) {
  const data = props.data;
  console.log(props.data);
  return (
    <div id="modal" className="modal hidden">
      <div className="container">
        <img
          src={closer}
          alt=""
          className="closer"
          onClick={() =>
            document.getElementById("modal").classList.add("hidden")
          }
        />
        <div className="modal-header flexbox">
          <img className="modal-img" src={data.sprite2} alt="" />
          <h2 className="modal-title-text">{data.name}</h2>
        </div>
        <div className="modal-description">
          <div id="types" className="flexbox">
            <h2>Types:</h2>
            <img
              src={process.env.PUBLIC_URL + types[data.type1]}
              alt=""
              className="type"
            />
            <img
              src={process.env.PUBLIC_URL + types[data.type2]}
              alt=""
              className="type"
            />
          </div>
          <div id="abilities" className="flexbox">
            <h2>Abiltities:</h2>
            <p className="ability">{data.ability1}</p>
            <p className="ability">{data.ability2}</p>
            <p className="ability">{data.ability3}</p>
          </div>

          <div className="flexbox stat-section">
            <h2>Stats:</h2>
            <div className="stats">
              <p>HP</p>
              <p>ATT</p>
              <p>DEF</p>
              <p>S.ATT</p>
              <p>S.DEF</p>
              <p>SPD</p>
            </div>
            <div id="stat-bars" className="stat-bars">
              <div style={{ width: data.hp }} className="stat-bar"></div>
              <div style={{ width: data.att }} className="stat-bar"></div>
              <div style={{ width: data.def }} className="stat-bar"></div>
              <div style={{ width: data.satt }} className="stat-bar"></div>
              <div style={{ width: data.sdef }} className="stat-bar"></div>
              <div style={{ width: data.spd }} className="stat-bar"></div>
            </div>
          </div>
          <div id="attributes" className="flexbox">
            <h2>
              Height:{" "}
              <span className="height">{(data.height * 0.1).toFixed(2)}m</span>
            </h2>
            <h2 className="attr">
              Weight:{" "}
              <span className="weight">{(data.weight * 0.1).toFixed(2)}kg</span>
            </h2>
          </div>
        </div>
      </div>
    </div>
  );
}
